// Small clips for the tests that need a stream Apple's own writer cannot
// make: VP9 in WebM, H.264 with B-frames in Matroska and full-range H.264 and
// HEVC in MP4. They are data, not code: each was written once, offline, by a
// standalone `ffmpeg` command (below) from a generated pattern, and is embedded as bytes the
// way the AV1 stream in apple_video_frame_test.mm is, so no encoder or muxer
// runs in the build or in a test.
//
// kVp9Webm: 128x96 (VideoToolbox's VP9 decoder refuses pictures much smaller
// than that), 30 frames at 30 per second, profile 0, 8-bit 4:2:0, a key frame at
// 0 and at 15, hidden alt-ref frames inside superframes.
//   ffmpeg -f lavfi -i testsrc2=size=128x96:rate=30 -frames:v 30 -pix_fmt yuv420p
//     -c:v libvpx-vp9 -b:v 20k -g 15 -lag-in-frames 5 -auto-alt-ref 1
//     -deadline good -cpu-used 4 -an -f webm clip.webm
//
// kH264Matroska: 64x48, 36 frames at 30 per second, High profile with two
// B-frames between anchors, a key frame every 18 frames, in a Matroska file
// (AVCC samples and an avcC CodecPrivate, the same layout as MP4).
//   ffmpeg -f lavfi -i testsrc2=size=64x48:rate=30 -frames:v 36 -pix_fmt yuv420p
//     -c:v h264_videotoolbox -profile:v high -b:v 40k -g 18 -bf 2 -an
//     -f matroska clip.mkv
